import json,re
d=json.load(open('mcp.json'))
def walk(o,p):
    if isinstance(o,dict):
        for k,v in o.items():
            if 'toggl' in k.lower():
                print('KEY', p+[k])
                if isinstance(v,dict):
                    for kk,vv in v.items():
                        if kk in ('tags','type','disabled','command','enabled'): print(' ',kk,vv)
                        elif kk=='url': print('  url',re.sub(r'\?.*','?<redacted>',vv))
                        else: print(' ',kk,'<redacted>', list(vv.keys()) if isinstance(vv,dict) else '')
            walk(v,p+[k])
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+[str(i)])
    elif isinstance(o,str) and 'toggl' in o.lower():
        print('VALUE at',p, '(len %d)'%len(o))
walk(d,[])
print('top keys',list(d.keys()))
EOF
